export function seriesLabels(language='EN'){const index=Math.max(0,langs.indexOf(language));return Object.fromEntries(Object.entries(words).map(([key,row])=>[key,row.split('|')[index]||row.split('|')[0]]));}

export function attachSeriesPlanner({getLanguage=()=> 'EN',getCurrent=()=>null,restore=()=>{},onPublish=null,getPublicationStatus=()=> 'none',storage=globalThis.localStorage}={}){
 if(document.getElementById('series-planner'))return null;
 const place=document.querySelector('.custom-library-toolbar')||document.getElementById('virtual-studio')||document.getElementById('creative-recipes');if(!place)return null;
 let store=createSeriesStore(storage);let current=store.list().at(-1)||createSeriesProject(),pending=false,template='cafe',statusKey=store.problem()?'saveError':'',cardViews=[];
 const previews=new Map(),t=()=>seriesLabels(getLanguage()),el=(tag,text='',cls='')=>{const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n;};
 const root=el('details','','series-planner');root.id='series-planner';const summary=el('summary'),body=el('div','','ser-body');root.append(summary,body);place.after(root);
 const shortcut=el('button');shortcut.id='series-planner-launcher';shortcut.type='button';shortcut.addEventListener('click',()=>{root.open=true;root.scrollIntoView({behavior:'smooth',block:'start'});});(document.querySelector('.custom-library-toolbar')||document.querySelector('.header-right'))?.append(shortcut);
 const status=el('p','','ser-status');status.setAttribute('role','status');status.setAttribute('aria-live','polite');let projectSelect,publicationProgress;
 const notify=key=>{statusKey=key;status.textContent=t()[key]||key;};
 const clearPreviews=()=>{for(const value of previews.values())URL.revokeObjectURL(value.url);previews.clear();};
 function save(){try{store.save(current);pending=false;notify('saved');updateProjects();document.dispatchEvent?.(new CustomEvent('prompt-studio-work-changed',{detail:{kind:'series',id:current.id}}));return true;}catch(error){pending=true;notify(['limit','conflict'].includes(error.message)?error.message:'saveError');return false;}}
 function updateProjects(){if(!projectSelect)return;const entries=store.list();if(!entries.some(p=>p.id===current.id))entries.push(current);projectSelect.replaceChildren(...entries.map(p=>new Option(p.id===current.id?current.title||t().name:p.title||t().name,p.id)));projectSelect.value=current.id;}
 const canLeave=()=>!pending||globalThis.confirm(t().unsaved);
 function selectProject(project){clearPreviews();current=normalizeSeriesProject(project);pending=false;statusKey='';render();document.dispatchEvent?.(new CustomEvent('prompt-studio-work-opened',{detail:{kind:'series',id:current.id}}));}
 function change(fn){fn();save();refreshPrompts();}
 function button(key,fn,parent){const n=el('button',t()[key]);n.type='button';n.dataset.serAction=key;n.addEventListener('click',fn);parent.append(n);return n;}
 function field(parent,key,value,type='text',handler,choices){
  const label=el('label'),caption=el('span',t()[key]||key),n=el(type==='textarea'?'textarea':type==='select'?'select':'input');
  if(!['textarea','select'].includes(type))n.type=type;if(type==='textarea'){n.rows=3;n.maxLength=key==='idea'?8000:6000;}else if(type==='text')n.maxLength=key==='name'||key==='sceneName'?120:3000;
  n.dataset.serField=key;
  if(choices)n.append(...choices.map(v=>new Option(t()[v]||v,v)));
  n.value=String(value??'');if(key==='seconds'){n.min='1';n.max='30';n.step='1';}
  if(handler)n.addEventListener(type==='select'?'change':'input',()=>handler(n.value));label.append(caption,n);parent.append(label);return n;
 }
 function download(text,suffix,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=(current.title.replace(/[^\p{L}\p{N}_-]+/gu,'_').slice(0,70)||'series')+suffix;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function promptBox(parent,scene,kind){
  const area=field(parent,kind,seriesScenePrompt(current,scene,kind),'textarea',value=>change(()=>{if(scene[kind+'Custom']===null)scene[kind+'Basis']=seriesSceneBasis(current,scene,kind);scene[kind+'Custom']=value;}));area.rows=7;area.maxLength=16000;
  const stale=el('p','','ser-stale');parent.append(stale);const actions=el('div','','ser-actions');parent.append(actions);
  button('copy',async()=>{try{await navigator.clipboard.writeText(seriesScenePrompt(current,scene,kind));notify('copied');}catch{notify('copyError');}},actions);
  button('refresh',()=>{if(scene[kind+'Custom']!==null&&!globalThis.confirm(t().confirmRefresh))return;change(()=>{scene[kind+'Custom']=null;scene[kind+'Basis']='';});},actions);
  button('use',()=>{if(getCurrent()?.prompt?.trim()&&!globalThis.confirm(t().replace))return;restore({mode:kind==='image'?'image':'i2v',prompt:seriesScenePrompt(current,scene,kind),language:'EN'});},actions);
  return {area,stale,kind};
 }
 function mediaBox(parent,scene,kind){
  const zone=el('div','','ser-media'),caption=el('p'),preview=el('div'),input=el('input');input.type='file';input.hidden=true;input.accept=kind==='image'?'image/png,image/jpeg,image/webp':'video/mp4,video/webm,video/quicktime';
  const key=scene.id+':'+kind;
  const refresh=()=>{caption.textContent=scene.media[kind+'Name']||'—';preview.replaceChildren();const reference=previews.get(key);if(reference){const media=el(kind==='image'?'img':'video');media.src=reference.url;if(kind==='image')media.alt=scene.media.imageName;else{media.controls=true;media.preload='metadata';}preview.append(media);}};
  const accept=file=>{if(!file)return;const allowed=kind==='image'?['image/png','image/jpeg','image/webp']:['video/mp4','video/webm','video/quicktime'];if(!allowed.includes(file.type)){notify('invalid');return;}
   if(previews.has(key))URL.revokeObjectURL(previews.get(key).url);previews.set(key,{url:URL.createObjectURL(file)});change(()=>{scene.media[kind+'Name']=file.name.slice(0,255);if(scene.status==='planned')scene.status='created';});refresh();const statusSelect=parent.querySelector('[data-ser-field="status"]');if(statusSelect)statusSelect.value=scene.status;};
  button(kind+'File',()=>{input.value='';input.click();},zone);input.addEventListener('change',()=>accept(input.files?.[0]));zone.append(input,caption,preview);
  button('forget',()=>{if(previews.has(key)){URL.revokeObjectURL(previews.get(key).url);previews.delete(key);}change(()=>scene.media[kind+'Name']='');refresh();},zone);
  zone.addEventListener('dragover',event=>event.preventDefault());zone.addEventListener('drop',event=>{event.preventDefault();event.stopPropagation();if(event.dataTransfer?.files?.length===1)accept(event.dataTransfer.files[0]);else notify('invalid');});parent.append(zone);refresh();
 }
 function refreshPublication(){if(publicationProgress){const state=getPublicationStatus(current);publicationProgress.textContent=t()[{none:"pubNone",working:"pubWorking",ready:"pubReady",stale:"pubStale"}[state]||"pubNone"];}}
 function refreshPrompts(){refreshPublication();for(const view of cardViews){view.status.value=view.scene.status;for(const prompt of view.prompts){const value=seriesScenePrompt(current,view.scene,prompt.kind);if(prompt.area.value!==value)prompt.area.value=value;prompt.stale.hidden=!seriesSceneStale(current,view.scene,prompt.kind);prompt.stale.textContent=t().stale;}}}
 function render(){
  summary.textContent=t().title;shortcut.textContent=t().title;body.replaceChildren();cardViews=[];
  body.append(el('p',t().intro,'ser-intro'),el('p',t().hint,'ser-help'));
  const toolbar=el('div','','ser-toolbar');body.append(toolbar);projectSelect=field(toolbar,'project',current.id,'select',value=>{const next=store.list().find(p=>p.id===value);if(next&&canLeave())selectProject(next);else projectSelect.value=current.id;},[]);updateProjects();
  field(toolbar,'template',template,'select',value=>template=value,seriesTemplates);
  button('new',()=>{if(canLeave()){selectProject(createSeriesProject(template));save();}},toolbar);
  button('duplicate',()=>{if(!canLeave())return;const project=parseSeriesProject(serializeSeriesProject(current));project.title=(current.title+' · '+t().copySuffix).slice(0,120);for(const scene of project.scenes){scene.status='planned';scene.media={imageName:'',videoName:''};}selectProject(project);save();},toolbar);
  button('save',save,toolbar);button('remove',()=>{if(!globalThis.confirm(t().confirmRemove))return;try{store.remove(current.id);selectProject(store.list().at(-1)||createSeriesProject(template));document.dispatchEvent?.(new CustomEvent('prompt-studio-work-changed',{detail:{kind:'series'}}));}catch{notify('saveError');}},toolbar);
  if(onPublish){button('publish',()=>onPublish(normalizeSeriesProject(current)),toolbar);publicationProgress=el('p','','ser-help');body.append(publicationProgress);refreshPublication();}
  field(body,'name',current.title,'text',value=>change(()=>current.title=value));
  const shared=el('details','','ser-shared');shared.open=true;shared.append(el('summary',t().shared));const grid=el('div','','ser-shared-grid');shared.append(grid);body.append(shared);
  for(const key of ['idea','location','subject','time','lighting','style','palette'])field(grid,key,current.shared[key],key==='idea'||key==='subject'?'textarea':'text',value=>change(()=>current.shared[key]=value));
  field(grid,'ratio',current.shared.ratio,'select',value=>change(()=>current.shared.ratio=value),['16:9','9:16','1:1','4:3','3:2']);
  button('current',()=>{const text=getCurrent()?.scenePrompt||getCurrent()?.prompt;if(!text?.trim()){notify('empty');return;}change(()=>current.shared.idea=text.slice(0,8000));render();},shared);
  const exportActions=el('div','','ser-actions');body.append(exportActions);button('export',()=>download(serializeSeriesProject(current),'.json','application/json'),exportActions);button('text',()=>download(exportSeriesText(current),'.txt','text/plain;charset=utf-8'),exportActions);
  const importInput=el('input');importInput.type='file';importInput.accept='.json,application/json';importInput.hidden=true;exportActions.append(importInput);
  button('import',()=>{importInput.value='';importInput.click();},exportActions);
  importInput.addEventListener('change',async()=>{const file=importInput.files?.[0];if(!file)return;try{if(file.size>300000)throw Error('format');const project=parseSeriesProject(await file.text());if(!canLeave())return;selectProject(project);save();}catch{notify('invalid');}});
  body.append(status);status.textContent=t()[statusKey]||'';
  const cards=el('div','','ser-cards');body.append(cards);
  current.scenes.forEach((scene,index)=>{
   const card=el('article','','ser-card');card.dataset.serScene=scene.id;card.append(el('h3',t().scene+' '+(index+1)));
   field(card,'sceneName',scene.title,'text',value=>change(()=>scene.title=value));field(card,'description',scene.description,'textarea',value=>change(()=>scene.description=value));field(card,'action',scene.action,'textarea',value=>change(()=>scene.action=value));
   const options=el('div','','ser-options');card.append(options);field(options,'framing',scene.framing,'select',value=>change(()=>scene.framing=value),seriesFramings);field(options,'motion',scene.motion,'select',value=>change(()=>scene.motion=value),seriesMotions);field(options,'seconds',scene.seconds,'number',value=>{const n=Number(value);if(Number.isFinite(n)&&n>=1&&n<=30)change(()=>scene.seconds=n);});const statusField=field(options,'status',scene.status,'select',value=>change(()=>scene.status=value),seriesStatuses);
   const prompts=[promptBox(card,scene,'image'),promptBox(card,scene,'video')];cardViews.push({scene,prompts,status:statusField});
   const media=el('div','','ser-media-grid');card.append(media);mediaBox(media,scene,'image');mediaBox(media,scene,'video');card.append(el('p',t().mediaHelp,'ser-help'));cards.append(card);
  });refreshPrompts();
 }
 document.addEventListener?.('prompt-studio-publication-status',refreshPublication);
 document.getElementById('ui-language')?.addEventListener('change',render);
 globalThis.addEventListener?.('beforeunload',event=>{if(pending){event.preventDefault();event.returnValue='';}});
 globalThis.addEventListener?.('pagehide',event=>{if(!event.persisted)clearPreviews();});

 function list(){const fresh=createSeriesStore(storage);if(fresh.problem())throw Error('storage');return fresh.list();}
 function resume(id,{scroll=true}={}){if(!canLeave())return false;try{const fresh=createSeriesStore(storage);if(fresh.problem())throw Error('storage');const found=fresh.list().find(p=>p.id===id);if(!found)return false;store=fresh;selectProject(found);root.open=true;if(scroll)root.scrollIntoView({behavior:'smooth',block:'start'});return true;}catch{notify('saveError');return false;}}
 render();return {list,resume,getState:()=>normalizeSeriesProject(current),save,translate:render,refreshPublication};
}
